{
  "predictors": [
    {
      "name": "CEO Tenure",
      "construction": "Number of years the current CEO has been in position.",
      "rationale": "Longer-tenured CEOs may have more firm-specific knowledge and experience, leading to better decision-making.",
      "higher_returns_for": "Firms with longer-tenured CEOs"
    },
    {
      "name": "Employee Satisfaction",
      "construction": "Measure of employee satisfaction from surveys or third-party ratings.",
      "rationale": "Higher employee satisfaction may lead to increased productivity and better firm performance.",
      "higher_returns_for": "Firms with higher employee satisfaction"
    },
    {
      "name": "Social Media Sentiment",
      "construction": "Measure of sentiment towards the firm on social media platforms.",
      "rationale": "Positive sentiment may indicate strong customer loyalty and brand strength.",
      "higher_returns_for": "Firms with more positive social media sentiment"
    },
    {
      "name": "Patent Activity",
      "construction": "Number of patents filed by the firm in the past year.",
      "rationale": "Patent activity may indicate innovative capacity and future growth potential.",
      "higher_returns_for": "Firms with higher patent activity"
    },
    {
      "name": "Customer Concentration",
      "construction": "Revenue concentration from the firm's largest customer.",
      "rationale": "High customer concentration may increase business risk due to dependence on a single customer.",
      "higher_returns_for": "Firms with lower customer concentration"
    },
    {
      "name": "Supplier Concentration",
      "construction": "Cost concentration from the firm's largest supplier.",
      "rationale": "High supplier concentration may increase business risk due to dependence on a single supplier.",
      "higher_returns_for": "Firms with lower supplier concentration"
    },
    {
      "name": "Product Diversity",
      "construction": "Number of distinct product lines or business segments.",
      "rationale": "Greater product diversity may reduce business risk and increase growth opportunities.",
      "higher_returns_for": "Firms with greater product diversity"
    },
    {
      "name": "Geographic Diversity",
      "construction": "Number of distinct geographic markets in which the firm operates.",
      "rationale": "Greater geographic diversity may reduce business risk and increase growth opportunities.",
      "higher_returns_for": "Firms with greater geographic diversity"
    },
    {
      "name": "Board Independence",
      "construction": "Proportion of the board of directors that is independent.",
      "rationale": "A more independent board may provide better oversight and reduce agency problems.",
      "higher_returns_for": "Firms with a higher proportion of independent directors"
    },
    {
      "name": "Environmental Impact",
      "construction": "Measure of the firm's environmental impact from third-party ratings or reports.",
      "rationale": "Firms with lower environmental impact may face less regulatory risk and have better public perception.",
      "higher_returns_for": "Firms with lower environmental impact"
    }
  ]
}
